<?php
namespace PharmaSure\Reporting\Services;
final class ScheduleService {
	private $db;private $p;public function __construct(){global $wpdb;$this->db=$wpdb;$this->p=$wpdb->prefix.'ps_';}
	public function create($tenant,$branch,array $data,$actor){$licence=(new \PharmaSure\Core\LicenseManager($tenant))->enforce_entitlement('reporting');if(is_wp_error($licence)){return $licence;}$limit=(int)($licence['quotas']['report_schedules']??0);if($limit>0){$count=(int)$this->db->get_var($this->db->prepare("SELECT COUNT(*) FROM {$this->p}report_schedules WHERE tenant_id=%d AND status IN ('active','paused')",$tenant));if($count>=$limit){return new \WP_Error('report_schedule_limit','The licensed scheduled-report limit has been reached.',array('status'=>409));}}$type=sanitize_key($data['report_type']??'');$format=sanitize_key($data['format']??'csv');$frequency=sanitize_key($data['frequency']??'');$recipients=array_values(array_unique(array_filter(array_map('sanitize_email',(array)($data['recipients']??array())))));if(!$type||!in_array($format,array('csv','xlsx','pdf'),true)||!in_array($frequency,array('daily','weekly','monthly'),true)||!$recipients){return new \WP_Error('invalid_schedule','Report type, format, daily/weekly/monthly frequency and valid recipients are required.',array('status'=>422));}$probe=(new ReportService())->report($type,$tenant,$branch,gmdate('Y-m-d'),gmdate('Y-m-d'));if(is_wp_error($probe)){return $probe;}$name=substr(sanitize_text_field($data['name']??ucwords($type).' report'),0,150);$next=$this->next($frequency,time());$this->db->insert($this->p.'report_schedules',array('tenant_id'=>$tenant,'branch_id'=>$branch?:null,'name'=>$name,'report_type'=>$type,'format'=>$format,'frequency'=>$frequency,'recipients'=>wp_json_encode($recipients),'next_run_at'=>gmdate('Y-m-d H:i:s',$next),'status'=>'active','created_by'=>$actor,'created_at'=>current_time('mysql',true)));if(!$this->db->insert_id){return new \WP_Error('schedule_not_created','Report schedule could not be saved.',array('status'=>500));}$id=(int)$this->db->insert_id;do_action('pharmasure_audit_log',array('tenant_id'=>$tenant,'actor_id'=>$actor,'action'=>'report.schedule_created','object_type'=>'report_schedule','object_id'=>$id,'details'=>array('branch_id'=>$branch,'report_type'=>$type,'format'=>$format,'frequency'=>$frequency,'recipient_count'=>count($recipients))));return array('id'=>$id,'name'=>$name,'next_run_at'=>gmdate('Y-m-d H:i:s',$next));}
	public function list_for_scope($tenant,$branch){$where='s.tenant_id=%d';$args=array($tenant);if($branch){$where.=' AND s.branch_id=%d';$args[]=$branch;}$sql=$this->db->prepare("SELECT s.id,s.branch_id,s.name,s.report_type,s.format,s.frequency,s.recipients,s.last_run_at,s.next_run_at,s.status,s.created_at,u.display_name AS created_by_name FROM {$this->p}report_schedules s LEFT JOIN {$this->db->users} u ON u.ID=s.created_by WHERE {$where} ORDER BY s.status='active' DESC,s.next_run_at ASC,s.id DESC",...$args);$rows=$this->db->get_results($sql,ARRAY_A);foreach($rows as &$row){$row['id']=(int)$row['id'];$row['branch_id']=(int)$row['branch_id'];$row['recipients']=array_values(array_filter((array)json_decode($row['recipients'],true)));}unset($row);return $rows;}
	public function recent_runs($tenant,$branch,$limit=12){$where='r.tenant_id=%d';$args=array($tenant);if($branch){$where.=' AND s.branch_id=%d';$args[]=$branch;}$args[]=max(1,min(50,(int)$limit));$sql=$this->db->prepare("SELECT r.id,r.schedule_id,r.status,r.period_from,r.period_to,r.row_count,r.error_message,r.started_at,r.finished_at,s.name,s.report_type,s.format FROM {$this->p}report_runs r INNER JOIN {$this->p}report_schedules s ON s.id=r.schedule_id AND s.tenant_id=r.tenant_id WHERE {$where} ORDER BY r.id DESC LIMIT %d",...$args);return $this->db->get_results($sql,ARRAY_A);}
	public function set_status($tenant,$branch,$id,$status,$actor){$status=sanitize_key($status);if(!in_array($status,array('active','paused'),true)){return new \WP_Error('invalid_schedule_status','Schedule status must be active or paused.',array('status'=>422));}$where='id=%d AND tenant_id=%d';$args=array($id,$tenant);if($branch){$where.=' AND branch_id=%d';$args[]=$branch;}$row=$this->db->get_row($this->db->prepare("SELECT id,status FROM {$this->p}report_schedules WHERE {$where} LIMIT 1",...$args),ARRAY_A);if(!$row){return new \WP_Error('schedule_not_found','The report schedule was not found in this pharmacy scope.',array('status'=>404));}if($row['status']==='running'){return new \WP_Error('schedule_running','A running schedule cannot be paused.',array('status'=>409));}$updated=$this->db->update($this->p.'report_schedules',array('status'=>$status,'updated_at'=>current_time('mysql',true)),array('id'=>(int)$id,'tenant_id'=>(int)$tenant));if(false===$updated){return new \WP_Error('schedule_not_updated','The report schedule could not be updated.',array('status'=>500));}do_action('pharmasure_audit_log',array('tenant_id'=>$tenant,'actor_id'=>$actor,'action'=>'report.schedule_status_changed','object_type'=>'report_schedule','object_id'=>$id,'before_state'=>array('status'=>$row['status']),'after_state'=>array('status'=>$status)));return array('id'=>(int)$id,'status'=>$status);}
	public static function run_due(){ $self=new self();$due=$self->db->get_results("SELECT * FROM {$self->p}report_schedules WHERE status='active' AND next_run_at<=UTC_TIMESTAMP() ORDER BY id LIMIT 20",ARRAY_A);foreach($due as $schedule){if(1===$self->db->update($self->p.'report_schedules',array('status'=>'running'),array('id'=>$schedule['id'],'status'=>'active'))){$self->run($schedule);}} }
	private function run($s){$to=gmdate('Y-m-d');$from=match($s['frequency']){'daily'=>gmdate('Y-m-d',strtotime('-1 day')),'weekly'=>gmdate('Y-m-d',strtotime('-7 days')),default=>gmdate('Y-m-01',strtotime('first day of last month'))};$report=(new ReportService())->report($s['report_type'],(int)$s['tenant_id'],(int)$s['branch_id'],$from,$to);$row_count=is_wp_error($report)?0:count($report['rows']??array());$this->db->insert($this->p.'report_runs',array('tenant_id'=>$s['tenant_id'],'schedule_id'=>$s['id'],'status'=>'running','period_from'=>$from,'period_to'=>$to,'row_count'=>$row_count,'started_at'=>current_time('mysql',true)));$run=(int)$this->db->insert_id;$exporter=new ExportService();$data=is_wp_error($report)?$report:$exporter->generate($s['format'],$s['report_type'],(int)$s['tenant_id'],(int)$s['branch_id'],$from,$to);$error='';$sent=false;$tmp='';if(is_wp_error($data)){$error=$data->get_error_message();}else{$tmp=wp_tempnam('pharmasure-report.'.$s['format']);file_put_contents($tmp,$data);$sent=wp_mail(json_decode($s['recipients'],true),'PharmaSure scheduled report: '.$s['name'],'Attached is your scheduled report for '.$from.' to '.$to,array(),array($tmp));if(!$sent){$error='WordPress mail delivery failed.';}}if($tmp&&file_exists($tmp)){unlink($tmp);}$status=$sent?'delivered':'failed';$this->db->update($this->p.'report_runs',array('status'=>$status,'error_message'=>$error?:null,'finished_at'=>current_time('mysql',true)),array('id'=>$run));$this->db->update($this->p.'report_schedules',array('status'=>'active','last_run_at'=>current_time('mysql',true),'next_run_at'=>gmdate('Y-m-d H:i:s',$this->next($s['frequency'],time())),'updated_at'=>current_time('mysql',true)),array('id'=>$s['id']));do_action('pharmasure_audit_log',array('tenant_id'=>$s['tenant_id'],'action'=>'report.schedule_'.$status,'object_type'=>'report_schedule','object_id'=>$s['id'],'details'=>array('run_id'=>$run,'row_count'=>$row_count,'error'=>$error)));}
	private function next($frequency,$time){return match($frequency){'daily'=>strtotime('+1 day',$time),'weekly'=>strtotime('+1 week',$time),default=>strtotime('+1 month',$time)};}
}
